internal sealed partial class Jobs(string state,string? fixtureRoot){
    private const string Version=Store.Version;
    internal sealed record Row(string Id,string RuleId,string Path,long Length,string LastWriteUtc,string FileIdentity);
    sealed record SealData(string Engine,string TaskId,string Scope,string Profile,bool Custom,string Status,string Hash,long Count,long Bytes,Rule[] Rules);
    sealed class Category(Rule r,string profile){public string RuleId=>r.Id;public string Name=>r.Id;public string Root=>r.Root;public string Group=>"快速清理";public string Risk=>"按规则复核";public string CleaningProfile=>profile;public int MinimumAgeHours=>r.Age;public string Note=>Status;public string Status{get;set;}="Success";public long Count{get;set;}public long Bytes{get;set;}}
    string TaskPath(string id){Require(Guid.TryParseExact(id,"D",out var g)&&g.ToString()==id,"InvalidTaskId");string t=Path.Combine(state,"Tasks",id);Private(state);Private(Path.GetDirectoryName(t)!);Private(t);var o=Open(Path.Combine(t,".task-owner"));Require(o.Str("TaskId")==id&&o.Str("Version")==Version&&o.GetProperty("SchemaVersion").GetInt32()==1&&o.Str("Path")==t&&o.Str("StateRoot")==state&&o.GetProperty("IsTest").GetBoolean()==(fixtureRoot!=null),"InvalidTaskOwner");return t;}
    static string Channel(string task,string p,bool optional=false){if(optional&&p=="")return "";Canon(p);Require(Path.GetDirectoryName(p)==task&&Regex.IsMatch(Path.GetFileName(p),"^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,99}$")&&!new[]{"candidates.jsonl","clean.claimed","execution.ledger","worker.active","core.active","clean.lock","task.completed","profile.invalidated","scan.meta.json","task.deleting"}.Contains(Path.GetFileName(p),StringComparer.OrdinalIgnoreCase),"InvalidTaskChannel");Plain(p,true);if(File.Exists(p))PlainFile(p);Require(!Directory.Exists(p),"ChannelIsDirectory");return p;}
    static bool Cancel(string p){if(p=="")return false;Plain(p,true);if(!File.Exists(p)){Require(!Directory.Exists(p),"InvalidCancelChannel");return false;}PlainFile(p);return true;}
    // Scan still checks at every walk checkpoint, but does not touch the disk at every entry.
    // Clean/Recycle continue to validate the cancellation channel before each existing action point.
    static readonly long ScanCancelInterval = (Stopwatch.Frequency + 39) / 40; // 25 ms
    string Scope(){if(fixtureRoot!=null)return Hash(fixtureRoot);string auth=Path.Combine(state,"cache-authorizations-v1.dpapi");return Hash(string.Join("|",File.Exists(auth)?Text(auth):"none",Environment.GetEnvironmentVariable("PIP_CACHE_DIR"),Environment.GetEnvironmentVariable("NUGET_HTTP_CACHE_PATH")));}
    static bool Invalidated(string t)=>Path.Exists(Path.Combine(t,"profile.invalidated"));
    static string[] Strings(JsonElement j,string key,int max){var a=j.GetProperty(key).EnumerateArray().Select(x=>x.GetString()??throw new InvalidDataException(key)).ToArray();Require(a.Length<=max&&a.Distinct().Count()==a.Length&&a.All(x=>x.Length is >0 and <1024),"Invalid"+key);return a;}
    static string J(object o)=>JsonSerializer.Serialize(o);
    public int Job(string action,string payloadPath,string outputPath){string? output=null,history=null,t=null;FileStream? lease=null;object result;string status="Failed";bool newClaimPossible=false;
        try{Require(action is "Scan" or "Clean" or "Recycle","UnknownOperation");string parent=Path.GetDirectoryName(Canon(payloadPath))!;t=TaskPath(Path.GetFileName(parent));Require(t==parent,"InvalidPayloadParent");Channel(t,payloadPath);string outPath=Channel(t,outputPath);var p=Obj(Text(payloadPath));string[] common=["TaskDirectory","ProgressPath","CancelPath"];p.Fields(action=="Scan"?[..common,"RuleIds","CleaningProfile","CustomEnabled"]:action=="Clean"?[..common,"ExcludedIds","RecycleMode","CleaningProfile","CustomEnabled"]:common);
            Require(p.Str("TaskDirectory")==t,"TaskMismatch");var progress=Channel(t,p.Str("ProgressPath"),true);var cancel=Channel(t,p.Str("CancelPath"),true);var channels=new[]{payloadPath,outPath,progress,cancel}.Where(x=>x!="").ToArray();Require(channels.Distinct(StringComparer.OrdinalIgnoreCase).Count()==channels.Length&&!File.Exists(outPath),"ChannelCollision");output=outPath;
            string lockFile=Path.Combine(t,"worker.active");if(File.Exists(lockFile))PlainFile(lockFile);lease=new FileStream(lockFile,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);Require(!File.Exists(Path.Combine(t,"task.deleting")),"TaskBeingRemoved");
            history=Path.Combine(t,".history-"+Guid.NewGuid().ToString("N"));HistoryWrite(history,t,action,"Unknown","工作进程没有封存最终结果，可能已部分处理。","");
            newClaimPossible=action=="Clean"&&!File.Exists(Path.Combine(t,"clean.claimed"));
            if(action=="Recycle"){Require(fixtureRoot==null,"FixtureCannotEmptyBin");var code=Cancel(cancel)?0x80004004u:SjcV3.Native.SHEmptyRecycleBin(IntPtr.Zero,null,6);status=code==0?"Success":code is 0x80004004u or 0x800704c7u?"Cancelled":"Failed";result=new{Version,Status=status,Error=code==0?"":"Shell:"+code,LogPath=output};}
            else {var profile=p.Str("CleaningProfile");bool custom=p.GetProperty("CustomEnabled").GetBoolean();result=action=="Scan"?Scan(t,profile,custom,Strings(p,"RuleIds",10000),progress,cancel,output):Clean(t,profile,custom,Strings(p,"ExcludedIds",1000000),p.GetProperty("RecycleMode").GetBoolean(),progress,cancel,output);status=JsonSerializer.SerializeToElement(result).Str("Status");}
        }catch(Exception e){status=newClaimPossible&&File.Exists(Path.Combine(t!,"clean.claimed"))?"Unknown":"Failed";result=status=="Unknown"?new{Version,Status=status,Error=e.Message,LogPath=output??""}:new{Version,Status=status,Error=e.Message,LogPath=output??"",Deleted=0,ProcessedBytes=0,Skipped=0};}
        try{if(output==null)return 2;Write(output,J(result));if(history!=null){var j=JsonSerializer.SerializeToElement(result);string summary=status is "Unknown" or "Failed"?"未完成："+j.Str("Error"):action=="Scan"?$"候选 {j.GetProperty("CandidateCount")} 个":action=="Clean"?$"处理 {j.GetProperty("Deleted")} 个，跳过 {j.GetProperty("Skipped")} 个":"系统回收站操作";HistoryWrite(history,t!,action,status,summary,output);Write(Path.Combine(t!,"task.completed"),Store.Seal(new{TaskDirectory=t,Status=status,UpdatedUtc=DateTime.UtcNow}),true);}return status=="Success"?0:1;}finally{lease?.Dispose();}
    }
    void HistoryWrite(string path,string task,string action,string status,string summary,string output)=>Write(path,Store.Seal(new{TaskDirectory=task,Action=action,Status=status,Summary=summary,LogPath=output,Time=DateTimeOffset.Now.ToString("o")}),File.Exists(path));
    static void Progress(string p,Stopwatch clock,string text,long reviewed,long count,bool force=false){if(p!=""&&(force||clock.ElapsedMilliseconds>=250)){Write(p,J(new{Text=text,Reviewed=reviewed,CandidateCount=count,UpdatedUtc=DateTime.UtcNow}),true);clock.Restart();}}
    object Scan(string t,string profile,bool custom,string[] selected,string progress,string cancel,string output){var all=Rules.Get(profile,state,fixtureRoot);Require(selected.Length>0&&selected.All(all.ContainsKey),"UnknownRule");if(!custom)Require(selected.ToHashSet().SetEquals(all.Values.Where(r=>r.Level<=Rules.Level(profile)).Select(r=>r.Id)),"PresetMismatch");var rules=selected.Select(id=>all[id]).ToArray();string scope=Scope(),path=Path.Combine(t,"candidates.jsonl");var cats=rules.ToDictionary(r=>r.Id,r=>new Category(r,profile));var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var clock=Stopwatch.StartNew();long reviewed=0,count=0,bytes=0;int warnings=0;var notes=new List<string>();bool cancelled=Cancel(cancel);var now=DateTime.UtcNow;
        long lastCancelProbe=Stopwatch.GetTimestamp();
        bool PollCancel(){if(cancel=="")return false;long stamp=Stopwatch.GetTimestamp();if(stamp-lastCancelProbe<ScanCancelInterval)return false;bool requested=Cancel(cancel);lastCancelProbe=stamp;return requested;}
        using(var f=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var wr=new StreamWriter(f,new UTF8Encoding(false))){foreach(var group in rules.GroupBy(r=>r.Root,StringComparer.OrdinalIgnoreCase)){if(cancelled)break;var active=new List<Rule>();foreach(var r in group){var cat=cats[r.Id];try{Plain(r.Root,true);cat.Status=Directory.Exists(r.Root)?r.Guard():"Missing";if(cat.Status=="Success")active.Add(r);}catch{cat.Status="Partial";warnings++;}}if(active.Count==0)continue;
            cancelled=!SjcV3.QuickClean.Walk(group.Key,PollCancel,d=>{Plain(d);return true;},file=>{reviewed++;foreach(var r in active){if(!r.Matches(file,now))continue;string guard=r.Guard();if(guard!="Success"){cats[r.Id].Status=guard;continue;}PlainFile(file.FullName);if(seen.Contains(file.FullName))break;var identity=SjcV3.Native.ReadIdentity(file.FullName);using(var probe=File.Open(file.FullName,FileMode.Open,FileAccess.Read,FileShare.None)){}file.Refresh();if(!r.Matches(file,now)||SjcV3.Native.ReadIdentity(file.FullName).Key!=identity.Key)continue;
                wr.WriteLine(J(new Row(Guid.NewGuid().ToString("N"),r.Id,file.FullName,file.Length,file.LastWriteTimeUtc.ToString("o"),identity.Key)));seen.Add(file.FullName);cats[r.Id].Count++;cats[r.Id].Bytes+=file.Length;count++;bytes+=file.Length;break;}Progress(progress,clock,"扫描候选",reviewed,count);},m=>{warnings++;if(notes.Count<200)notes.Add(m);foreach(var r in active)cats[r.Id].Status="Partial";});}}
        Require(scope==Scope(),"ScopeChanged");using var stream=File.OpenRead(path);string hash=Convert.ToHexString(SHA256.HashData(stream));cancelled=cancelled||Cancel(cancel);
        string status=cancelled?"Cancelled":cats.Values.Any(x=>x.Status is not ("Success" or "Missing"))?"Partial":"Success";var meta=new SealData("QuickClean/1",Path.GetFileName(t),scope,profile,custom,status,hash,count,bytes,rules);Write(Path.Combine(t,"scan.meta.json"),Store.Seal(meta));Progress(progress,clock,"扫描结束",reviewed,count,true);return new{Version,TaskId=Path.GetFileName(t),Status=status,CleaningProfile=profile,CustomEnabled=custom,Categories=cats.Values,CandidateCount=count,CandidateBytes=bytes,Reviewed=reviewed,WarningCount=warnings,Warnings=notes,Error="",LogPath=output,PlanPath=path};}
    (FileStream,SealData) Plan(string t){var m=Open(Path.Combine(t,"scan.meta.json")).Deserialize<SealData>()!;Require(m.Engine=="QuickClean/1"&&m.TaskId==Path.GetFileName(t)&&m.Scope==Scope()&&!Invalidated(t),"PlanInvalidated");string path=Path.Combine(t,"candidates.jsonl");PlainFile(path);var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);try{Require(Convert.ToHexString(SHA256.HashData(f))==m.Hash,"PlanHashMismatch");f.Position=0;return(f,m);}catch{f.Dispose();throw;}}
    object Clean(string t,string profile,bool custom,string[] excluded,bool recycle,string progress,string cancel,string output){var(f,m)=Plan(t);using(f){Require(m.Profile==profile&&m.Custom==custom&&m.Status is "Success" or "Partial","PlanModeMismatch");var all=Rules.Get(profile,state,fixtureRoot);Require(m.Rules.All(r=>all.GetValueOrDefault(r.Id)==r),"RuleBindingChanged");var rules=m.Rules.ToDictionary(r=>r.Id);var clock=Stopwatch.StartNew();var result=SjcV3.QuickClean.Execute(f,t,m.Count,m.Bytes,excluded,line=>{var r=Obj(line).Deserialize<Row>()!;Require(Guid.TryParseExact(r.Id,"N",out _)&&r.Length>=0&&rules.TryGetValue(r.RuleId,out var rule)&&Within(Canon(r.Path),rule.Root),"InvalidCandidate");return [r.Id,r.RuleId,r.Path,r.Length.ToString(),r.LastWriteUtc,r.FileIdentity];},()=>Cancel(cancel),x=>{var r=rules[x[1]];var file=new FileInfo(x[2]);long size=long.Parse(x[3]),ticks=DateTime.ParseExact(x[4],"o",null,System.Globalization.DateTimeStyles.RoundtripKind).Ticks;
            Require(!Invalidated(t)&&Scope()==m.Scope,"ScopeChanged");if(r.Binding!="")Require(Rules.Get(profile,state,fixtureRoot).GetValueOrDefault(r.Id)==r,"AuthorizationChanged");PlainFile(file.FullName);Require(r.Guard()=="Success"&&r.Matches(file,DateTime.UtcNow)&&file.Length==size&&file.LastWriteTimeUtc.Ticks==ticks&&SjcV3.Native.ReadIdentity(file.FullName).Key==x[5],"FileOrPolicyChanged");using(var probe=File.Open(file.FullName,FileMode.Open,FileAccess.Read,FileShare.None)){}if(recycle)SjcV3.RecycleSink.Move(file.FullName,x[5],size,ticks);else SjcV3.Native.DeleteSnapshot(file.FullName,x[5],size,ticks);},(reviewed,total)=>Progress(progress,clock,"复核并处理封存候选",reviewed,total),()=>{});
        return new{Version,TaskId=Path.GetFileName(t),CleaningProfile=profile,CustomEnabled=custom,result.Status,result.Deleted,result.Skipped,result.Reviewed,result.ProcessedBytes,result.ErrorCount,Errors=result.Errors.ToArray(),LogPath=output,Error=""};}}
}
